function ensureCasino(){
  const required=["package.json","package-lock.json","index.html","src/App.tsx","src/main.tsx","src/context/CasinoContext.jsx","src/styles/index.css"];
  if(required.every(rel=>fs.existsSync(path.join(casino,rel)))){console.log("[railway] full casino source present");return;}
  console.log("[railway] restoring full casino source from single-file bundle");
  for(const [rel,b64] of Object.entries(embedded)){const out=path.join(casino,rel);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,Buffer.from(b64,"base64"));}
}
function run(cmd,args,cwd){console.log("[railway]",cmd,args.join(" "));const r=cp.spawnSync(cmd,args,{cwd,stdio:"inherit",shell:false});if(r.status!==0)process.exit(r.status||1);}
